package br.com.fiap.bank.core.infrastructure;
import org.springframework.stereotype.Repository;import br.com.fiap.bank.core.domain.*;import java.util.*;@Repository public class ContaAdapter implements ContaRepository {private final ContaSpringRepository db;public ContaAdapter(ContaSpringRepository db){this.db=db;}private Conta toDomain(ContaJpa x){return new Conta(x.numeroConta,x.cpfCliente,x.agencia,x.tipoConta,x.saldo,x.ativa);}public Conta save(Conta c){ContaJpa x=new ContaJpa();x.numeroConta=c.numeroConta();x.cpfCliente=c.cpfCliente();x.agencia=c.agencia();x.tipoConta=c.tipoConta();x.saldo=c.saldo();x.ativa=c.ativa();return toDomain(db.save(x));}public Optional<Conta> byNumero(String n){return db.findById(n).map(this::toDomain);}public List<Conta> byCpf(String cpf){return db.findByCpfCliente(cpf).stream().map(this::toDomain).toList();}public List<Conta> all(){return db.findAll().stream().map(this::toDomain).toList();}}